#/bin/bash

python -c 'from pathlib import Path; from markdown_it import MarkdownIt; import html; src=Path("提交.md"); body=MarkdownIt("commonmark", {"html": True}).enable("table").render(src.read_text(encoding="utf-8")); css="""@page { size: A4; margin: 18mm 16mm; } body { font-family: \"Noto Sans CJK SC\", \"WenQuanYi Micro Hei\", \"Microsoft YaHei\", sans-serif; color: #222; font-size: 11pt; line-height: 1.55; } h1 { font-size: 22pt; border-bottom: 2px solid #444; padding-bottom: 6px; page-break-after: avoid; } h2 { font-size: 16pt; margin-top: 1.4em; page-break-after: avoid; } h3 { page-break-after: avoid; } table { width: 100%; border-collapse: collapse; font-size: 9pt; margin: 12px 0; } th, td { border: 1px solid #777; padding: 6px; vertical-align: top; word-break: break-word; } th { background: #eee; } pre { white-space: pre-wrap; overflow-wrap: anywhere; background: #f5f5f5; border: 1px solid #ddd; padding: 10px; font-size: 8pt; line-height: 1.35; } code { font-family: \"Noto Sans Mono CJK SC\", \"DejaVu Sans Mono\", monospace; } blockquote { border-left: 4px solid #aaa; margin-left: 0; padding-left: 12px; color: #555; } li { margin: 3px 0; } p { orphans: 3; widows: 3; }"""; doc="<!doctype html><html lang=\"zh-CN\"><head><meta charset=\"utf-8\"><title>提交</title><style>"+css+"</style></head><body>"+body+"</body></html>"; Path(".提交_pdf_temp.html").write_text(doc, encoding="utf-8")' && google-chrome --headless --no-sandbox --disable-gpu --no-pdf-header-footer --print-to-pdf="/home/wxf/HPU/DSCI5800_魏_兴峰_练习1.pdf" "file:///home/wxf/HPU/.提交_pdf_temp.html"